const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([45.203, 4.735]); // Beledweyne, Somalia
  const region = point.buffer(50000); // 50km buffer
  const may2017 = ee.DateRange('2017-05-01', '2017-05-31');
  const may2018 = ee.DateRange('2018-05-01', '2018-05-31');

  // 2. Data Acquisition - SMAP 10km soil moisture
  const getCollection = (dateRange) => {
    return ee.ImageCollection('NASA_USDA/HSL/SMAP10KM_soil_moisture')
      .filterDate(dateRange.start(), dateRange.end())
      .filterBounds(region)
      .select(['ssm', 'ssm_qd']);
  };

  const col2017 = getCollection(may2017);
  const col2018 = getCollection(may2018);

  const size2017 = col2017.size().getInfo();
  const size2018 = col2018.size().getInfo();
  console.log(`May 2017 Images: ${size2017}`);
  console.log(`May 2018 Images: ${size2018}`);

  // Case 1: Empty collection check
  if (size2017 === 0 || size2018 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing with quality masking (ssm_qd: 0=good, 1=acceptable, 2=poor)
  const processCollection = (collection) => {
    return collection
      .map(img => {
        const mask = img.select('ssm_qd').lte(1); // Keep good/acceptable
        return img.select('ssm').updateMask(mask);
      })
      .median()
      .clip(region);
  };

  const soil2017 = processCollection(col2017);
  const soil2018 = processCollection(col2018);

  // 4. Calculate pixel counts and means
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2017 = soil2017.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: 10000, // SMAP native 10km resolution
    maxPixels: 1e9
  }).getInfo();

  const stats2018 = soil2018.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const mean2017 = stats2017.ssm;
  const mean2018 = stats2018.ssm;
  const count2017 = stats2017.ssm_count;
  const count2018 = stats2018.ssm_count;

  console.log(`2017 Mean: ${mean2017?.toFixed(2) ?? 'null'}, Valid Pixels: ${count2017}`);
  console.log(`2018 Mean: ${mean2018?.toFixed(2) ?? 'null'}, Valid Pixels: ${count2018}`);

  // Case 2: No valid pixels
  if (count2017 === 0 || count2018 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Case 3: Calculation failure
  if (mean2017 === null || mean2018 === null || 
      isNaN(mean2017) || isNaN(mean2018)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Valid range check (SSM typically 0-100 mm)
  if (mean2017 > 100 || mean2017 < 0 || mean2018 > 100 || mean2018 < 0) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Final comparison
  console.log(`Difference (2018-2017): ${(mean2018 - mean2017).toFixed(2)} mm`);
  if (mean2018 > mean2017) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
